// Stands in for vite-plugin-pwa's virtual module under Vitest (see vitest.config.ts alias),
// since that module is only generated by the real plugin at dev/build time.
export function useRegisterSW() {
  return {
    needRefresh: [false, () => {}] as const,
    offlineReady: [false, () => {}] as const,
    updateServiceWorker: async () => {},
  };
}
